const d = (s) => new Date(s);
const out = [];
await b.recordUnsubscribe("Ann <<EMAIL>>", d("2026-10-23T09:00Z"));
out.push(["unsub marketing (alias: <EMAIL>)", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T10:00Z"))]);
out.push(["unsub transactional (alias)", b.mayEmail({to:"<EMAIL>",kind:"transactional"}, d("2026-10-23T10:00Z"))]);
out.push(["other person still marketing-ok", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T10:00Z"))]);
await b.recordResubscribe("<EMAIL>", d("2026-10-23T12:00Z"));
out.push(["resub later clears", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T13:00Z"))]);
await b.recordUnsubscribe("<EMAIL>", d("2026-10-23T12:00Z"));
await b.recordResubscribe("<EMAIL>", d("2026-10-23T11:00Z"));
out.push(["resub earlier than unsub arrives late -> still blocked", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T13:00Z"))]);
await b.recordUnsubscribe("<EMAIL>", d("2026-10-23T11:30Z"));
out.push(["older extra unsub changes nothing -> blocked", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T13:00Z"))]);
await b.recordResubscribe("<EMAIL>", d("2026-10-23T14:00Z"));
out.push(["resub after latest unsub -> allowed", b.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T15:00Z"))]);
const fresh = await import("./bot.mjs?x=" + Math.random());
out.push(["restart (fresh module): unsub state visible", fresh.mayEmail({to:"<EMAIL>",kind:"marketing"}, d("2026-10-23T10:00Z"))]);
await Promise.all([1,2,3,4,5].map(i => b.recordUnsubscribe("<EMAIL>", d("2026-10-23T16:0"+i+"Z"))));
