for (const [k,v] of out) console.log(k.padEnd(56), JSON.stringify(v));
' ; echo "exit=$?"; echo "events dirs: $(ls "$STATE_DIR/events" | wc -l)  tmp leftovers: $(ls "$STATE_DIR/tmp" | wc -l)"; rm -rf "$STATE_DIR"

